dict(slug='inventario', ilus='INV', wa=P_WA, adv=PAULO,
 title='Inventário em cartório ou na Justiça: como resolver a herança',
 desc='Perdeu um familiar e precisa fazer o inventário? Veja quando é possível fazer em cartório, quando precisa ser judicial, quais documentos separar e como funciona o atendimento. Fale pelo WhatsApp.',
 msg='Olá, Dr. Paulo! Encontrei o escritório pelo Google e tenho uma questão sobre inventário. Gostaria de uma orientação.',
 eyebrow='Inventário e partilha de bens',
 h1='Inventário sem complicação: <em>do cartório à partilha.</em>',
 lead='Organizamos o inventário do início ao fim. Você reúne os documentos, nós analisamos se o caminho mais rápido e econômico é o cartório ou a Justiça e conduzimos cada etapa até a partilha dos bens.',
 cta='Falar sobre o inventário',
 chips=['Análise da melhor via','Atendimento on-line','Etapas acompanhadas'],
 hip_t='Quando você precisa de um inventário', hip=[
  ('Falecimento com bens','Imóveis, veículos, contas, aplicações ou participação em empresas deixados pelo falecido.'),
  ('Imóvel no nome de quem faleceu','Para vender, financiar ou transferir o imóvel, é preciso concluir o inventário e registrar a partilha.'),
  ('Valores em banco ou previdência','Saldos, aplicações e restituições que dependem de inventário ou de autorização para levantamento.'),
  ('Herdeiros em desacordo','Quando não há consenso sobre a divisão, o inventário segue pela via judicial.'),
  ('Inventário parado ou antigo','Inventários que não foram abertos no prazo ou que estão parados há anos podem ser retomados.'),
  ('Bens descobertos depois','Quando surgem bens após a partilha, é possível fazer a sobrepartilha.')],
 info_t='O que diz a lei',
 info='O inventário extrajudicial, feito por escritura pública em cartório, é admitido quando os herdeiros estão de acordo e assistidos por advogado (CPC, art. 610, § 1º e § 2º). A Resolução CNJ nº 571/2024 ampliou essa possibilidade também para casos com testamento ou herdeiro menor, desde que cumpridos os requisitos previstos. Havendo divergência entre os herdeiros, ou fora dessas hipóteses, o inventário é judicial. O CPC prevê que o inventário seja aberto em até 2 meses do falecimento (art. 611), e o atraso pode gerar multa no ITCMD, conforme a lei estadual.',
 docs=['Certidão de óbito','Documentos pessoais do falecido e dos herdeiros, com certidões de casamento ou nascimento','Matrículas atualizadas dos imóveis e documentos dos veículos','Extratos bancários e de aplicações na data do falecimento','Testamento, se houver, e pacto antenupcial ou contrato de união estável'],
 prazo='o inventário deve ser aberto em até 2 meses do falecimento (CPC, art. 611). Mesmo fora desse prazo, ainda é possível fazer, e quanto antes, menor o custo com multas.',
 comp=[('Extrajudicial (cartório)',['Herdeiros de acordo sobre a divisão','Escritura pública no tabelionato, com advogado','Costuma ser concluído em semanas, conforme a documentação','Possível também com testamento ou herdeiro menor, nos termos da Resolução CNJ 571/2024']),
  ('Judicial (Justiça)',['Herdeiros em desacordo ou situações fora das hipóteses do cartório','Processo na Vara de Família e Sucessões','Prazo depende da tramitação e de eventuais disputas','Permite alvarás para vender bens ou levantar valores durante o processo'])],
 steps_t='Do primeiro contato <em>à partilha</em>', steps=[
  ('Primeiro contato','Você conta pelo WhatsApp quem faleceu, quem são os herdeiros e quais bens existem.'),
  ('Lista de documentos','Enviamos a lista completa do que reunir, com orientação sobre onde obter cada certidão.'),
  ('Análise da via','Com os documentos em mãos, avaliamos se o inventário pode ser feito em cartório ou se deve ser judicial, e explicamos custos e prazos.'),
  ('Impostos e minuta','Calculamos e orientamos o recolhimento do ITCMD e preparamos a minuta da escritura ou a petição inicial.'),
  ('Partilha concluída','Acompanhamos a assinatura da escritura ou o processo até a sentença e o registro dos bens em nome dos herdeiros.')],
 faq=[('Quanto tempo demora um inventário?','Em cartório, com a documentação completa e o imposto pago, costuma levar poucas semanas. O judicial depende da tramitação e do consenso entre os herdeiros.'),
  ('Todos os herdeiros precisam estar de acordo?','Para o cartório, sim. Sem acordo, o inventário segue pela via judicial.'),
  ('Passou do prazo de 2 meses. Ainda dá para fazer?','Sim. O inventário pode ser aberto a qualquer tempo; o atraso pode apenas gerar multa no imposto, conforme a lei estadual.'),
  ('Preciso ir até o escritório?','Não necessariamente. O atendimento pode ser feito pelo WhatsApp e por videochamada, com reuniões presenciais quando for conveniente.')]),
dict(slug='holding-familiar', ilus='HOL', wa=P_WA, adv=PAULO,
 title='Holding familiar: planejamento sucessório e proteção do patrimônio',
 desc='Quer organizar a sucessão da família, evitar um inventário demorado e reduzir conflitos entre herdeiros? Veja quando a holding familiar faz sentido e como funciona o planejamento. Fale pelo WhatsApp.',
 msg='Olá, Dr. Paulo! Encontrei o escritório pelo Google e tenho interesse em planejamento sucessório e holding familiar. Gostaria de uma orientação.',
 eyebrow='Planejamento sucessório e holding familiar',
 h1='Organize hoje a sucessão <em>que sua família vai viver amanhã.</em>',
 lead='A holding familiar é uma das ferramentas do planejamento sucessório. Estudamos o patrimônio e a família para indicar o melhor caminho, com holding, doação, testamento ou a combinação deles.',
 cta='Conversar sobre planejamento',
 chips=['Estudo de viabilidade','Sigilo e discrição','Atendimento on-line ou presencial'],
 hip_t='Quando vale a pena planejar', hip=[
  ('Imóveis e patrimônio relevante','Famílias com imóveis, empresas ou investimentos que precisam de uma transição organizada.'),
  ('Evitar o inventário','A sucessão planejada em vida reduz a necessidade de inventário e os custos e a demora que ele envolve.'),
  ('Prevenir conflitos entre herdeiros','Regras claras de administração e divisão definidas pelos próprios donos do patrimônio.'),
  ('Empresa familiar','Continuidade do negócio e definição de quem administra quando houver a sucessão.'),
  ('Imóveis alugados','Organização da gestão dos aluguéis em uma estrutura própria, com análise tributária caso a caso.'),
  ('Proteção do patrimônio da família','Cláusulas na doação de quotas, como usufruto, incomunicabilidade e inalienabilidade.')],
 info_t='O que é a holding familiar',
 info='É uma sociedade criada para concentrar bens da família, como imóveis e participações em empresas. Os pais transferem os bens para a sociedade e, em seguida, podem doar as quotas aos filhos, reservando para si o usufruto e a administração. Na doação, é possível incluir cláusulas de incomunicabilidade, impenhorabilidade e inalienabilidade (Código Civil, art. 1.911), respeitando a parte legítima dos herdeiros necessários (art. 1.846). A integralização de imóveis tem tratamento tributário específico (Constituição, art. 156, § 2º, I), que deve ser analisado caso a caso. A holding não é indicada para todas as famílias: o estudo prévio compara custos, tributos e alternativas.',
 docs=['Relação dos bens: imóveis, empresas, investimentos e veículos','Matrículas atualizadas dos imóveis','Documentos pessoais e certidão de casamento ou de união estável, com pacto antenupcial, se houver','Contratos sociais das empresas da família, se houver','Informações sobre aluguéis e despesas dos imóveis'],
 prazo='o planejamento precisa ser feito em vida e com os titulares plenamente capazes. Quanto antes, mais opções e menos custos para a família.',
 comp=[('Com planejamento',['Regras definidas pelos próprios titulares','Transição organizada e previsível','Menos espaço para disputas entre herdeiros','Custos e tributos estudados com antecedência']),
  ('Sem planejamento',['Inventário obrigatório após o falecimento','Bens podem ficar bloqueados até a partilha','Decisões tomadas em momento de luto','Risco maior de conflito e de demora'])],
 comp_t='Com ou sem planejamento sucessório',
 comp_note='Cada família tem uma solução própria. A análise do patrimônio e dos objetivos é a primeira etapa do atendimento.',
 steps_t='Etapas do <em>planejamento</em>', steps=[
  ('Conversa inicial','Entendemos a família, os bens e o que se espera do planejamento, com total sigilo.'),
  ('Diagnóstico','Levantamos o patrimônio e os documentos e mapeamos os riscos da sucessão.'),
  ('Estudo de viabilidade','Comparamos holding, doação e testamento, com estimativa de custos e tributos de cada caminho.'),
  ('Estruturação','Elaboramos contrato social, acordo de quotistas, doações e cláusulas de proteção.'),
  ('Registro e acompanhamento','Registramos os atos e acompanhamos a família nas decisões seguintes.')],
 faq=[('A holding serve para qualquer família?','Não. Ela costuma fazer sentido quando há imóveis ou empresas em valor relevante. O estudo de viabilidade indica se compensa ou se outro caminho é melhor.'),
  ('A holding elimina o pagamento de impostos?','Não. Ela pode organizar e, em alguns casos, reduzir custos, mas os tributos devem ser analisados caso a caso, conforme a lei e o município.'),
  ('Os pais perdem o controle dos bens?','Não necessariamente. É comum doar as quotas com reserva de usufruto, mantendo a administração e a renda com os pais.'),
  ('Atendem fora de Poços de Caldas?','Sim. O atendimento é feito também por videochamada, em todo o Brasil.')]),
